SELECT DISTINCT ca.score FROM "ConditionAssessments" ca ORDER BY ca.score LIMIT 10;

-- What if "serious maintenance issues" means treat_stat is NOT 'Not Required' AND prio_tag in ('High', 'Urgent')?
SELECT COUNT(DISTINCT m."case_ID") FROM (
    SELECT m."case_ID", c.treat_stat, c.prio_tag
    FROM "Monitor_Showcase_Map" m
    JOIN "ConservationAndMaintenance" c ON m."mon_ID" = c.monitor_link
) sub WHERE treat_stat != 'Not Required' AND prio_tag IN ('High', 'Urgent');

SELECT COUNT(DISTINCT sub.case_ID) FROM (
    SELECT m."case_ID", c.prio_tag, c.treat_stat
    FROM "Monitor_Showcase_Map" m
    JOIN "ConservationAndMaintenance" c ON m."mon_ID" = c.monitor_link
) sub WHERE sub.prio_tag IN ('High', 'Urgent');

